files.examples/01_text.sql:
CREATE TABLE users (
  full_name text       NOT NULL,  -- no arbitrary limit: the usual choice
  handle    varchar(6) NOT NULL   -- the limit is checked on every write
);

INSERT INTO users VALUES
  ('Şükrü Işık',   'şükrü'),
  ('İpek Çağlar',  'ipekç'),
  ('Ada Lovelace', 'ada');

-- length() counts characters, octet_length() counts UTF-8 bytes.
-- varchar(n) counts characters too: 'şükrü' fits in 6 although it is 8 bytes.
SELECT handle, length(handle) AS chars, octet_length(handle) AS bytes
FROM users
ORDER BY handle;

-- Case mapping follows the collation. The database default maps i to I;
-- Turkish rules need an ICU collation.
SELECT upper(handle) AS default_rules,
       upper(handle COLLATE "tr-x-icu") AS turkish_rules
FROM users
ORDER BY handle;

-- An explicit cast to varchar(n) truncates silently (the SQL standard says so)...
SELECT 'kahramanmaraşlı'::varchar(6) AS cast_result;

-- ...but storing an over-long value is an error.
INSERT INTO users VALUES ('Kahramanmaraşlı Ayşe', 'kahramanmaraşlı');

files.examples/02_integers.sql:
-- integer: 4 bytes, up to 2,147,483,647. bigint: 8 bytes, up to about 9.2e18.
SELECT pg_column_size(1::integer) AS integer_bytes,
       pg_column_size(1::bigint)  AS bigint_bytes;

-- Division of two integers truncates toward zero, as in Go, C and Java.
-- Python's -7 // 2 is -4; here -7 / 2 is -3. One numeric operand changes the type.
SELECT 7 / 2 AS int_div, -7 / 2 AS neg_div, 7 % 2 AS remainder, 7 / 2.0 AS numeric_div;

CREATE TABLE counters (
  page text    PRIMARY KEY,
  hits integer NOT NULL
);
INSERT INTO counters VALUES ('home', 2147483647), ('about', 1);

-- Aggregates widen their result: sum(integer) returns bigint, so this works.
SELECT sum(hits) AS total, pg_typeof(sum(hits)) AS total_type FROM counters;

-- Row arithmetic does not widen. One more hit on 'home' leaves integer's
-- range, and Postgres raises an error instead of wrapping around.
UPDATE counters SET hits = hits + 1 WHERE page = 'home';

files.examples/03_money.sql:
-- A literal with a decimal point is numeric (exact) unless you cast it.
SELECT pg_typeof(0.1) AS literal_type,
       0.1 + 0.2 = 0.3 AS numeric_equal,
       0.1::float8 + 0.2::float8 = 0.3::float8 AS float_equal,
       0.1::float8 + 0.2::float8 AS float_sum;

CREATE TABLE payments (
  amount numeric(12, 2)   NOT NULL,  -- exact: 10 digits before the point, 2 after
  approx double precision NOT NULL   -- the mistake, kept for comparison
);

-- Ten payments of 0.10 TL.
INSERT INTO payments SELECT 0.10, 0.10 FROM generate_series(1, 10);

SELECT sum(amount) AS exact_total,
       sum(approx) AS float_total,
       sum(approx) = 1 AS float_total_is_one
FROM payments;

-- numeric(12, 2) rounds extra decimals on the way in, ties away from zero.
-- round() on a float rounds ties to even (on most platforms).
SELECT 19.995::numeric(12, 2) AS stored_as,
       round(2.5) AS numeric_round,
       round(2.5::float8) AS float_round;

-- Too many digits before the point is an error, never a silent wrap.
INSERT INTO payments VALUES (12345678901.00, 0);
